mapper.select:
select DATE_FORMAT(`order_create_time`,#{param.dateExp}) as `period`, sum(received_price) as amount from canteen_order
order_create_time between #{param.period.begin} and #{param.period.end}
GROUP BY DATE_FORMAT(`order_create_time`,#{param.dateExp})

SELECT t2.`user_name`, t2.`amount` from ( select t1.`name` as user_name, sum(t1.received_price) as amount from canteen_order t1
order_create_time between #{param.period.begin} and #{param.period.end}
GROUP BY t1.`name` ) t2 ORDER BY t2.`amount` DESC

select t1.`window_name` as window_name, sum(t1.received_price) as amount from canteen_order t1
order_create_time between #{param.period.begin} and #{param.period.end}
GROUP BY t1.`window_name`

select DATE_FORMAT(`order_create_time`,#{param.dateExp}) as `period`, count(distinct t1.`name`) as person_count from canteen_order t1
order_create_time between #{param.period.begin} and #{param.period.end}
GROUP BY DATE_FORMAT(`order_create_time`,#{param.dateExp})
